package br.com.onda;
import android.app.*;
import android.content.*;
import android.database.Cursor;
import android.graphics.*;
import android.net.Uri;
import android.os.*;
import android.provider.*;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;

@androidx.media3.common.util.UnstableApi
public class ConnectActivity extends Activity {
 private static final int FILES=7510,FOLDER=7511,SCAN=7512,QR_IMAGE=7513;
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());
 private final List<Uri> sources=new ArrayList<>();private final List<ConnectProtocol.FileInfo> files=new ArrayList<>();
 private TextView status,selection;private ImageView qr;private EditText code;private Button choose,receive,send,scan,image,copy,stop;private ProgressBar progress;
 private volatile ConnectSession session;private int generation;private boolean active,dead;private Bitmap qrBitmap;private AlertDialog approval;private String pairCode="";
 @Override public void onCreate(Bundle state){super.onCreate(state);LinearLayout root=column();Ui.background(root);root.setOnApplyWindowInsetsListener((v,i)->{root.setPadding(Ui.dp(this,16),Ui.dp(this,12)+i.getSystemWindowInsetTop(),Ui.dp(this,16),Ui.dp(this,12)+i.getSystemWindowInsetBottom());return i;});setContentView(root);
  LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);Button back=Ui.button(this,"‹",v->finish());Ui.ghost(back);back.setContentDescription("Voltar do Onda Conecta");header.addView(back,new LinearLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,48)));TextView title=Ui.text(this,"Onda Conecta",23,Ui.TEXT);Ui.bold(title);header.addView(title,new LinearLayout.LayoutParams(0,-2,1));root.addView(header);
  ScrollView scroll=new ScrollView(this);LinearLayout body=column();scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  body.addView(label("ENVIE PELA REDE WI-FI",11,Ui.CYAN));body.addView(label("Músicas, vídeos e PDFs entre celulares com Onda. Sem conta nem servidor. Mantenha esta tela aberta nos dois aparelhos; sair interrompe a transferência.",14,Ui.MUTED));
  receive=Ui.button(this,"Receber • escolher pasta e gerar QR",v->folder());receive.setContentDescription("Receber arquivos pelo Conecta");body.addView(receive);
  qr=new ImageView(this);qr.setContentDescription("QR de pareamento do Onda Conecta");qr.setAdjustViewBounds(true);qr.setVisibility(View.GONE);body.addView(qr,new LinearLayout.LayoutParams(-1,Ui.dp(this,250)));copy=Ui.button(this,"Copiar código de conexão",v->{if(!pairCode.isEmpty())((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Onda Conecta",pairCode));});copy.setVisibility(View.GONE);body.addView(copy);
  body.addView(label("OU ENVIE DESTE CELULAR",11,Ui.CYAN));choose=Ui.button(this,"1. Escolher arquivos",v->pickFiles());choose.setContentDescription("Escolher arquivos para enviar");body.addView(choose);
  selection=label("Nenhum arquivo selecionado",13,Ui.MUTED);selection.setContentDescription("Arquivos selecionados no Conecta");body.addView(selection);
  scan=Ui.button(this,"2. Ler QR com a câmera",v->startActivityForResult(new Intent(this,ConnectScanActivity.class),SCAN));scan.setContentDescription("Ler QR do outro celular");body.addView(scan);image=Ui.button(this,"Ler QR de uma imagem",v->startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("image/*"),QR_IMAGE));body.addView(image);
  code=new EditText(this);Ui.input(code);code.setHint("Ou cole o código do outro celular");code.setContentDescription("Código de conexão do Conecta");body.addView(code);
  send=Ui.button(this,"3. Conectar e enviar",v->{try{beginSend(ConnectProtocol.Pair.parse(code.getText().toString()));}catch(Exception e){say("Leia ou cole um código Conecta válido do outro celular.");}});send.setContentDescription("Conectar e enviar arquivos");Ui.primary(send);body.addView(send);
  status=label("Pronto. Use a mesma rede Wi-Fi nos dois celulares.",14,Ui.CYAN);status.setContentDescription("Estado do Onda Conecta");root.addView(status);progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(1000);root.addView(progress,new LinearLayout.LayoutParams(-1,Ui.dp(this,12)));
  stop=Ui.button(this,"Cancelar transferência",v->cancel("Cancelado. Os arquivos já concluídos foram mantidos."));root.addView(stop);
  body.addView(label("Até 10 arquivos, 512 MB por arquivo e 1 GB por envio. O receptor precisa aceitar a lista. O QR expira após 3 minutos de espera e é usado uma vez. Não compartilhe o código fora dos aparelhos envolvidos. Redes de convidados ou isolamento Wi-Fi podem impedir a conexão. Nesta versão, um envio interrompido precisa ser iniciado novamente.",12,Ui.MUTED));controls();
 }
 private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
 private TextView label(String text,int size,int color){TextView t=Ui.text(this,text,size,color);t.setPadding(0,Ui.dp(this,12),0,Ui.dp(this,12));return t;}
 private void say(String text){Toast.makeText(this,text,Toast.LENGTH_LONG).show();}
 private void controls(){choose.setEnabled(!active);receive.setEnabled(!active);send.setEnabled(!active&&!files.isEmpty());scan.setEnabled(!active&&!files.isEmpty());image.setEnabled(!active&&!files.isEmpty());code.setEnabled(!active);stop.setEnabled(active);if(active)getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);else getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);}
 private void folder(){Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);try{startActivityForResult(intent,FOLDER);}catch(ActivityNotFoundException e){say("Seletor de pastas indisponível neste celular.");}}
 private void pickFiles(){try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*").putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true).putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"audio/*","video/*","application/pdf"}).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION),FILES);}catch(ActivityNotFoundException e){say("Seletor de arquivos indisponível neste celular.");}}
 private void clearQr(){pairCode="";qr.setImageDrawable(null);qr.setVisibility(View.GONE);copy.setVisibility(View.GONE);if(qrBitmap!=null){qrBitmap.recycle();qrBitmap=null;}}
 private void cancel(String message){generation++;ConnectSession old=session;session=null;if(old!=null)old.close();if(approval!=null){approval.dismiss();approval=null;}active=false;clearQr();status.setText(message);controls();}
 private ConnectSession.Listener listener(int token){return new ConnectSession.Listener(){private void ui(Runnable action){main.post(()->{if(!dead&&token==generation)action.run();});}
  public void pair(ConnectProtocol.Pair pair){try{Bitmap bitmap=ConnectQr.make(pair.code(),640);main.post(()->{if(dead||token!=generation){bitmap.recycle();return;}pairCode=pair.code();qrBitmap=bitmap;qr.setImageBitmap(bitmap);qr.setVisibility(View.VISIBLE);copy.setVisibility(View.VISIBLE);status.setText("No outro celular: escolha os arquivos e leia este QR. Aguardando conexão por até 3 minutos.");});}catch(Exception e){ConnectSession current=session;if(current!=null)current.close();}}
  public void offer(List<ConnectProtocol.FileInfo> offered,java.util.function.Consumer<Boolean> answer){ui(()->{clearQr();StringBuilder message=new StringBuilder();for(ConnectProtocol.FileInfo f:offered)message.append(f.name).append(" • ").append(size(f.size)).append('\n');message.append("\nSalvar na pasta que você escolheu?");approval=new AlertDialog.Builder(ConnectActivity.this).setTitle("Aceitar "+offered.size()+" arquivos?").setMessage(message.toString()).setPositiveButton("Aceitar",(d,w)->answer.accept(true)).setNegativeButton("Recusar",(d,w)->answer.accept(false)).setOnCancelListener(d->answer.accept(false)).show();});}
  public void progress(String text,long done,long total){ui(()->{status.setText(text+"\n"+size(done)+" de "+size(total));progress.setProgress(total==0?0:(int)(1000*done/total));});}
  public void finished(boolean success,int completed,String message){ui(()->{session=null;active=false;if(approval!=null){approval.dismiss();approval=null;}clearQr();status.setText(message+"\n"+completed+" arquivo(s) confirmado(s). Os recebidos ficam na pasta escolhida no aparelho receptor e no Meu espaço, conforme capacidade.");if(success)progress.setProgress(1000);controls();});}
 };}
 private void beginReceive(Uri tree){if(active)return;active=true;progress.setProgress(0);int token=++generation;controls();status.setText("Preparando conexão local segura…");session=new ConnectSession(listener(token));ConnectSession run=session;worker.execute(()->{try{ConnectNetwork network=ConnectNetwork.wifi(this);javax.net.ssl.SSLContext tls=ConnectTls.server();run.receive(tls,network.host,ConnectTls.pin(),info->ConnectStorage.create(this,tree,info));}catch(Exception e){main.post(()->{if(!dead&&generation==token)cancel("Conecte os aparelhos à mesma rede Wi-Fi privada e tente novamente.");});}});}
 private void beginSend(ConnectProtocol.Pair pair){if(active||files.isEmpty())return;List<Uri> uris=new ArrayList<>(sources);List<ConnectProtocol.FileInfo> offered=new ArrayList<>(files);active=true;progress.setProgress(0);int token=++generation;controls();status.setText("Conectando ao outro celular…");session=new ConnectSession(listener(token));ConnectSession run=session;worker.execute(()->{try{ConnectNetwork network=ConnectNetwork.wifi(this);run.send(ConnectTls.client(pair.pin),pair,offered,i->{InputStream in=getContentResolver().openInputStream(uris.get(i));if(in==null)throw new IOException();return in;},network.network.getSocketFactory());}catch(Exception e){main.post(()->{if(!dead&&generation==token)cancel("Conecte os aparelhos à mesma rede Wi-Fi privada e gere um novo QR.");});}});}
 static String size(long bytes){return String.format(Locale.getDefault(),bytes>=1024*1024?"%.1f MB":"%.1f KB",bytes/(bytes>=1024*1024?1048576.0:1024.0));}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null)return;if(request==SCAN){String value=data.getStringExtra("code");if(value!=null)code.setText(value);return;}if(data.getData()==null&&data.getClipData()==null)return;
  if(request==FOLDER){Uri tree=data.getData();if(tree==null)return;try{getContentResolver().takePersistableUriPermission(tree,data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION));}catch(RuntimeException ignored){}beginReceive(tree);return;}
  if(request==QR_IMAGE){Uri uri=data.getData();if(uri==null)return;worker.execute(()->{Bitmap bitmap=null;try{BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;try(InputStream in=getContentResolver().openInputStream(uri)){BitmapFactory.decodeStream(in,null,bounds);}if(bounds.outWidth<=0||bounds.outHeight<=0)throw new IOException();BitmapFactory.Options options=new BitmapFactory.Options();while((long)bounds.outWidth*bounds.outHeight/(options.inSampleSize==0?1:(long)options.inSampleSize*options.inSampleSize)>2000000)options.inSampleSize=options.inSampleSize==0?2:options.inSampleSize*2;try(InputStream in=getContentResolver().openInputStream(uri)){bitmap=BitmapFactory.decodeStream(in,null,options);}if(bitmap==null)throw new IOException();String value=ConnectQr.read(bitmap);ConnectProtocol.Pair.parse(value);main.post(()->{if(!dead)code.setText(value);});}catch(Exception e){main.post(()->{if(!dead)say("Não encontrei um QR válido do Onda Conecta na imagem.");});}finally{if(bitmap!=null)bitmap.recycle();}});return;}
  if(request==FILES){List<Uri> selected=new ArrayList<>();if(data.getClipData()!=null){int count=data.getClipData().getItemCount();if(count>ConnectProtocol.FILES){say("Selecione no máximo 10 arquivos.");return;}for(int i=0;i<count;i++)selected.add(data.getClipData().getItemAt(i).getUri());}else if(data.getData()!=null)selected.add(data.getData());for(Uri u:selected)try{getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(RuntimeException ignored){}worker.execute(()->{try{List<ConnectProtocol.FileInfo> metadata=new ArrayList<>();for(Uri u:selected){String name=null,mime=getContentResolver().getType(u);long bytes=-1;try(Cursor c=getContentResolver().query(u,new String[]{OpenableColumns.DISPLAY_NAME,OpenableColumns.SIZE},null,null,null)){if(c!=null&&c.moveToFirst()){name=c.getString(0);if(!c.isNull(1))bytes=c.getLong(1);}}metadata.add(new ConnectProtocol.FileInfo(name,mime,bytes));}long total=ConnectProtocol.total(metadata);main.post(()->{if(dead)return;sources.clear();sources.addAll(selected);files.clear();files.addAll(metadata);StringBuilder text=new StringBuilder(metadata.size()+" arquivo(s) • "+size(total));for(ConnectProtocol.FileInfo f:metadata)text.append("\n").append(f.name);selection.setText(text);controls();});}catch(Exception e){main.post(()->{if(!dead)say("Selecione até 10 áudios, vídeos ou PDFs locais, até 512 MB cada e 1 GB no total. O provedor precisa informar o tamanho.");});}});}
 }
 @Override protected void onStop(){if(active)cancel("Transferência interrompida ao sair da tela. Gere um novo QR para tentar novamente.");super.onStop();}
 @Override protected void onDestroy(){dead=true;generation++;ConnectSession run=session;if(run!=null)run.close();worker.shutdownNow();main.removeCallbacksAndMessages(null);clearQr();super.onDestroy();}
}
